import sys, json

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def render_content(content):
    out = []
    if isinstance(content, str):
        out.append(trunc(content, 500))
        return out
    if not isinstance(content, list):
        return [trunc(content)]
    for block in content:
        if not isinstance(block, dict):
            out.append(trunc(block))
            continue
        t = block.get("type")
        if t == "text":
            out.append("TEXT: " + trunc(block.get("text", ""), 500))
        elif t == "tool_use":
            out.append(f"TOOL_USE {block.get('name')}: " + trunc(json.dumps(block.get("input", {})), 300))
        elif t == "tool_result":
            c = block.get("content")
            out.append("TOOL_RESULT: " + trunc(c, 300))
        elif t == "thinking":
            out.append("THINKING: " + trunc(block.get("thinking", ""), 200))
        else:
            out.append(f"{t}: " + trunc(block, 200))
    return out

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        d = json.loads(line)
        typ = d.get("type")
        ts = d.get("timestamp", "")
        if typ in ("assistant", "user"):
            msg = d.get("message", {})
            role = msg.get("role", typ)
            content = msg.get("content", "")
            for c in render_content(content):
                print(f"[{ts}] {role}: {c}")
        elif typ == "queue-operation":
            print(f"[{ts}] QUEUE({d.get('operation')}): " + trunc(d.get("content", ""), 300))

